/* libsomrando: C port of Moppu/SecretOfManaRandomizer v1.49 (commit 1404b7b).  LGPL-2.1 or later, see sr_core.h and COPYING.LIB.
 *
 * MagicRopeRefactor (Author: Moppleton), derived from SoMRandomizer/processing/hacks/openworld/MagicRopeRefactor.cs.  Translated to C 2026-10-18.
 * The map -> door table is generated by tools/gen_p4_hmisc_rope.py.
 */
#include "sr_core.h"
#include "sr_p4.h"
#include "sr_p4_hk_misc_rope_data.h"

#define E(v) sr_emit(c, (v))
#define P(off, v) sr_poke(c, (off), (v))

int sr_p4_hack_magic_rope_refactor(struct sr_ctx *c) {
  if (!sr_settings_get_bool(c->settings, "opMagicRopeRefactor")) return 0;

  int tableLocation = c->working_offset;
  for (int i = 0; i < 512; i++) {
    E((uint8_t)sr_p4_hmisc_rope_doors[i]);
    E((uint8_t)(sr_p4_hmisc_rope_doors[i] >> 8));
  }

    // code changes - ignore map flags, and read what goes into $0108 for the "return" door from the map above,
    // instead of storing it on a transition from outdoor to indoor maps and keeping it around
    /*
      $02/AB18 29 20 20    AND #$2020              A:8080 X:0004 Y:0004 P:eNvmXdIzc
      $02/AB1B F0 10       BEQ $10    [$AB2D]      A:0000 X:0004 Y:0004 P:envmXdIZc - remove
      $02/AB1D C9 20 20    CMP #$2020              A:2000 X:0001 Y:0004 P:envmXdIzc
      $02/AB20 F0 0B       BEQ $0B    [$AB2D]      A:2000 X:0001 Y:0004 P:eNvmXdIzc - remove
      $02/AB22 49 20 00    EOR #$0020              A:2000 X:0001 Y:0004 P:eNvmXdIzc
      $02/AB25 F0 03       BEQ $03    [$AB2A]      A:2020 X:0001 Y:0004 P:envmXdIzc - change to branch always
      $02/AB27 AD 0E 01    LDA $010E  [$00:010E]   A:2020 X:0001 Y:0004 P:envmXdIzc - load current door (skip now)
      $02/AB2A 8D 08 01    STA $0108  [$00:0108]   A:00D3 X:0001 Y:0004 P:envmXdIzc - save door for rope (replace)
      $02/AB2D E2 20       SEP #$20                A:00D3 X:0001 Y:0004 P:envmXdIzc - replace
      $02/AB2F 6B          RTL                     A:00D3 X:0001 Y:0004 P:envMXdIzc
    */

    P(0x2AB1B, 0xEA);
    P(0x2AB1C, 0xEA);

    P(0x2AB20, 0xEA);
    P(0x2AB21, 0xEA);

    P(0x2AB25, 0x80); // branch always

    P(0x2AB2A, 0x22);
    P(0x2AB2B, (uint8_t)(c->working_offset));
    P(0x2AB2C, (uint8_t)(c->working_offset >> 8));
    P(0x2AB2D, (uint8_t)((c->working_offset >> 16) + 0xC0));
    P(0x2AB2E, 0xEA);
    // REP 10
    E(0xC2);
    E(0x10);
    // PHA
    E(0x48);
    // PHX
    E(0xDA);
    // LDA $7E00DC
    E(0xAF);
    E(0xDC);
    E(0x00);
    E(0x7E);
    // ASL
    E(0x0A);
    // TAX
    E(0xAA);
    // LDA $______,x
    E(0xBF);
    E((uint8_t)tableLocation);
    E((uint8_t)(tableLocation >> 8));
    E((uint8_t)((tableLocation >> 16) + 0xC0));
    // BEQ over
    E(0xF0);
    E(0x0D);
    // PHA
    E(0x48);
    // LDA $7E011E
    E(0xAF);
    E(0x1E);
    E(0x01);
    E(0x7E);
    // ORA #4000
    E(0x09);
    E(0x00);
    E(0x40);
    // STA $7E011E - set magic rope available flag
    E(0x8F);
    E(0x1E);
    E(0x01);
    E(0x7E);
    // PLA
    E(0x68);
    // over:
    // STA $0108
    E(0x8D);
    E(0x08);
    E(0x01);
    // PLX
    E(0xFA);
    // PLA
    E(0x68);
    // SEP 30
    E(0xE2);
    E(0x30);
    // RTL
    E(0x6B);
  return 1;
}
